    'config.text_browser.allowed_private_hosts.help': "可以放宽公网地址 SSRF 检查的内网主机，支持精确匹配和子域名；* 允许 RFC 1918、回环和 .local，默认空列表即拒绝，但 169.254.0.0/16、Azure 168.63.129.16、阿里云 100.100.100.200、AWS fd00:ec2::/64、GCP fd20:ce::254 及其已识别的 IPv4 内嵌形式在解析后仍然拦截。外部浏览器会重新解析 DNS 并跟随重定向且不再校验，所以这不是 DNS 重绑定或重定向边界；本地预检仍可能拒绝只能通过浏览器或代理解析的名字，网址或 DNS 由攻击者控制时优先使用 web_fetch。",
