    'config.section.web_fetch': "网页抓取",
    'config.section.web_fetch.help': "抓取网页并把 HTML 转成纯文本。allowed_domains 控制可访问的主机（[\"*\"] 表示全部公网），blocked_domains 优先于允许列表，允许列表为空则拒绝全部请求；同主机重定向会跟随，跨主机重定向会被拒绝，以便已校验的 DNS 保持钉在这次传输上。",
    'config.web_fetch.enabled': "启用",
    'config.web_fetch.enabled.help': "是否启用 web_fetch。默认开启。",
    'config.web_fetch.allowed_domains': "允许的域名",
    'config.web_fetch.allowed_domains.help': "允许抓取的域名，支持精确匹配和子域名；[\"*\"] 表示全部公网主机，列表为空则拒绝全部请求。",
    'config.web_fetch.blocked_domains': "禁止的域名",
    'config.web_fetch.blocked_domains.help': "禁止抓取的域名，支持精确匹配和子域名，并始终优先于允许的域名。",
    'config.web_fetch.allowed_private_hosts': "允许的内网主机",
    'config.web_fetch.allowed_private_hosts.help': "放宽公网地址 SSRF 检查的私有或内部主机，支持精确匹配和子域名；目标仍在本地解析，已知云元数据与平台地址始终拦截，列在这里的字面私有或本机主机还会绕过 allowed_domains。* 允许任意字面私有或本机主机，并让已在 allowed_domains 中的名字解析到私有 IP，但不会扩大 allowed_domains；标准请求必须直连以钉住 DNS，可选的 Firecrawl API 回退则使用环境代理发现。",
    'config.web_fetch.max_response_size': "最大响应（字节）",
    'config.web_fetch.max_response_size.help': "响应体上限，单位字节。默认 500000（500KB），纯文本通常比原始 HTML 小得多。",
